function wheel(FWD, cx, cy, cz, r, w, type, hub) {
  for (var a = -r; a <= r; a++) for (var b = -r; b <= r; b++) {
    if (a * a + b * b > r * r + r) continue;
    if (r >= 5 && a * a + b * b < (r - 2) * (r - 2) && a !== 0 && b !== 0 && Math.abs(a) !== Math.abs(b)) continue;
    for (var t = 0; t < w; t++) {
      if (FWD === "z") block(cx + t, cy + b, cz + a, type);
      else block(cx + a, cy + b, cz + t, type);
    }
  }
  if (hub) block(FWD === "z" ? cx - 1 : cx, cy, FWD === "z" ? cz : cz - 1, hub);
}

function cylinder(cx, cy, cz, r, type) {
  for (var x = cx - r; x <= cx + r; x++) {
    for (var y = cy - r; y <= cy + r; y++) {
      for (var z = cz - r; z <= cz + r; z++) {
        var dx = x - cx, dy = y - cy, dz = z - cz;
        if (dx * dx + dy * dy + dz * dz <= r * r) block(x, y, z, type);
      }
    }
  }
}

function hollowCylinder(cx, cy, cz, rOuter, rInner, h, type) {
  for (var x = cx - rOuter; x <= cx + rOuter; x++) {
    for (var y = cy - rOuter; y <= cy + rOuter; y++) {
      for (var z = cz - rOuter; z <= cz + rOuter; z++) {
        var dx = x - cx, dy = y - cy, dz = z - cz;
        var d2 = dx * dx + dy * dy + dz * dz;
        if (d2 <= rOuter * rOuter && d2 > rInner * rInner) block(x, y, z, type);
      }
    }
  }
}

